import type { FieldStatus, ReportFields } from "@/api";
import { fieldDefByPath } from "@/report/schema";

// Questions the nurse asks, in the order of the 醫院檢傷問診病人查核表 (#87, TOCC first for infection control).
// A fixed list written by people, never generated by the AI. An item is ticked only from whether its report
// fields have a value; nothing here judges whether the value is right.
export interface ChecklistItem {
  id: string;
  question: string;
  fields: string[]; // all of them need a value for the item to count as answered
  note?: string; // a reminder for the nurse, shown under the question
}

export const nurseChecklist: ChecklistItem[] = [
  { id: "fever", question: "目前有發燒、咳嗽或感冒症狀嗎？", fields: ["tocc.fever_cough_cold"] },
  { id: "travel", question: "過去兩個月內有去過國內或國外旅遊嗎？", fields: ["tocc.travel"] },
  { id: "occ", question: "職業？接觸史？群聚？", fields: ["tocc.occupation", "tocc.contact", "tocc.cluster"] },
  { id: "arms", question: "兩隻手都可以量血壓嗎？", fields: ["measurement.restrictions"], note: "不能碰處戴「禁止治療」手圈" },
  { id: "cc", question: "這次是哪裡不舒服來掛急診？", fields: ["chief_complaint"], note: "再深入詢問（現在病史）" },
  { id: "dob", question: "出生年月日？", fields: ["patient.dob"] },
  { id: "with", question: "今天有家屬陪同嗎？", fields: ["patient.accompanied_by"] },
  { id: "walk", question: "走路可以嗎？需要輪椅嗎？", fields: ["patient.mobility"] },
];

// 未問: no field has a value. 部分: some do. Otherwise the item is answered, and its status says who answered it:
// 護理師已確認 only when every field is confirmed by the nurse, else AI 草稿.
export type ChecklistStatus = "未問" | "部分" | Exclude<FieldStatus, "未提及">;

export interface ChecklistRow extends ChecklistItem {
  status: ChecklistStatus;
  missing: string[]; // labels of the fields still empty
  jumpTo: string; // the first empty field, or the first field still a draft, or the first field
}

export function checklistRows(fields: ReportFields): ChecklistRow[] {
  return nurseChecklist.map((item) => {
    const statusOf = (p: string) => fields[p]?.status ?? "未提及";
    const empty = item.fields.filter((p) => statusOf(p) === "未提及");
    const draft = item.fields.find((p) => statusOf(p) === "AI 草稿");
    const status: ChecklistStatus =
      empty.length === item.fields.length ? "未問" : empty.length ? "部分" : draft ? "AI 草稿" : "護理師已確認";
    return {
      ...item,
      status,
      missing: empty.map((p) => fieldDefByPath(p)?.label ?? p),
      jumpTo: empty[0] ?? draft ?? item.fields[0],
    };
  });
}
